// Get the output string from the AI Agent node
const rawText = $input.first().json.output || $input.first().json.text || "";

// 1. Regular expression to find content between triple backticks
const jsonRegex = /```(?:json)?\s*([\s\S]*?)\s*```/;
const match = rawText.match(jsonRegex);

// 2. Determine which string to parse
let stringToParse = match ? match[1] : rawText;

try {
  // 3. Clean up common invisible characters and parse
  const cleanJson = JSON.parse(stringToParse.trim());

  // 4. Academic level normalization mapping
  const levelMap = {
    'junior secondary 1': ['js1', 'jss1', 'basic7', 'js 1', 'jss 1', 'basic 7'],
    'junior secondary 2': ['js2', 'jss2', 'basic8', 'js 2', 'jss 2', 'basic 8'],
    'junior secondary 3': ['js3', 'jss3', 'basic9', 'js 3', 'jss 3', 'basic 9'],
    'senior secondary 1': ['ss1', 'sss1', 'ss 1', 'sss 1'],
    'senior secondary 2': ['ss2', 'sss2', 'ss 2', 'sss 2'],
    'senior secondary 3': ['ss3', 'sss3', 'ss 3', 'sss 3']
  };

  // 5. Function to match and normalize the level
  const normalizeLevel = (rawLevel) => {
    if (!rawLevel) return "";
    const cleanRaw = rawLevel.toLowerCase().trim();

    for (const [standardizedLevel, variations] of Object.entries(levelMap)) {
      if (variations.includes(cleanRaw)) {
        return standardizedLevel;
      }
    }
    return rawLevel;
  };

  // Return as a standard n8n object
  return {
    student_name: cleanJson.student_name,
    level: normalizeLevel(cleanJson.level),
    amount: cleanJson.amount,
    date: cleanJson.date,
    narration: cleanJson.narration
  };
} catch (error) {
  throw new Error("Failed to parse AI output into JSON. Raw text was: " + rawText);
}

const parentInputName = $( "Code in JavaScript" ).first().json.student_name.toLowerCase().trim();
const parentTokens = parentInputName.split(/\s+/).filter(t => t.length > 2); // ["osieta", "favour"]

let studentsFromDb = [];
try {
  studentsFromDb = $( "Fetch Level Students" ).all();
} catch (e) {
  return { match_found: false, error: "Database Query node not found." };
}

function getLevenshteinDistance(a, b) {
  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) matrix[i][j] = matrix[i - 1][j - 1];
      else matrix[i][j] = Math.min(matrix[i - 1][j - 1] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j] + 1);
    }
  }
  return matrix[b.length][a.length];
}

const results = studentsFromDb.map(item => {
  const dbFullName = (item.json.full_name || "").toLowerCase().trim();
  const dbTokens = dbFullName.split(/\s+/);

  // 1. TOKEN MATCH (The "Middle Name" Savior)
  // Counts how many words from the parent input appear in the DB name
  let matchedTokens = 0;
  parentTokens.forEach(pToken => {
    if (dbTokens.some(dbToken => dbToken.includes(pToken) || pToken.includes(dbToken))) {
      matchedTokens++;
    }
  });
  const tokenScore = parentTokens.length > 0 ? (matchedTokens / parentTokens.length) : 0;

  // 2. FUZZY SCORE (The "Typo" Savior)
  const distance = getLevenshteinDistance(parentInputName, dbFullName);
  const maxLength = Math.max(parentInputName.length, dbFullName.length);
  const fuzzyConfidence = maxLength === 0 ? 0 : 1 - (distance / maxLength);

  // 3. ENHANCED MATCH LOGIC
  let finalScore = fuzzyConfidence;

  // If all parent words match (like "Osieta" and "Favour"), 
  // we give it a 95% boost even if the middle name is long.
  if (tokenScore === 1) {
    finalScore = Math.max(finalScore, 0.95);
  } else if (tokenScore >= 0.5) {
    // If at least half the words match, boost the fuzzy score
    finalScore = Math.max(finalScore, 0.85);
  }

  return { ...item.json, match_confidence: finalScore };
});

// 1. Filter for all students who look like a match (Threshold 0.8)
const likelyMatches = results.filter(r => r.match_confidence >= 0.8);
likelyMatches.sort((a, b) => b.match_confidence - a.match_confidence);

// 2. Handle Twins/Ambiguity
if (likelyMatches.length > 1) {
  const scoreDiff = likelyMatches[0].match_confidence - likelyMatches[1].match_confidence;
  if (scoreDiff < 0.05) { 
    return {
      match_found: false,
      is_ambiguous: true,
      potential_matches: likelyMatches.map(m => m.full_name),
      message: "Multiple students found with similar names."
    };
  }
}

// 3. Proceed with single best match
if (likelyMatches.length > 0) {
  return {
    match_found: true,
    is_ambiguous: false,
    student_id: likelyMatches[0].student_id,
    full_name: likelyMatches[0].full_name,
    confidence: Math.round(likelyMatches[0].match_confidence * 100) + "%"
  };
}

return { match_found: false, is_ambiguous: false, message: "No student found." };

// 1. Check if the previous node returned an error
const response = $input.first().json;
const isError = response.status === 'error' || response.error_detail;

if (isError) {
  // If it's an error, don't try to process binary data
  return {
    json: {
      ...response,
      process_success: false,
      error_display_message: response.error_detail || "An unexpected error occurred."
    }
  };
}

// 2. Success Path: Process the Base64 image
const base64String = response.data?.receipt_image;

if (!base64String) {
  return {
    json: { 
      process_success: false, 
      error_display_message: "No receipt image was returned by the server." 
    }
  };
}

const binaryData = Buffer.from(base64String, 'base64');

return {
  binary: {
    data: {
      data: binaryData.toString('base64'),
      fileName: 'receipt.png',
      fileExtension: 'png',
      mimeType: 'image/png',
    }
  },
  json: {
    ...response,
    process_success: true
  }
};

// 1. Detect and parse the error shape
const item = $input.first().json;

let response = {};
let isError = false;
let httpCode = 200;

function extractPhpBody(errMsg) {
  if (!errMsg) return null;

  // n8n wraps PHP responses as: <code> - "<json body>"
  // Strip the prefix
  let candidate = errMsg.replace(/^\d+\s*-\s*/, '').trim();

  // Strip surrounding quotes if present
  if (candidate.startsWith('"') && candidate.endsWith('"')) {
    candidate = candidate.slice(1, -1);
  }

  try {
    return JSON.parse(candidate);
  } catch (e) {
    // Fallback: find first { to last }
    const match = candidate.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) {}
    }
    return null;
  }
}

if (item.error) {
  isError = true;
  httpCode = parseInt(item.error.status) || parseInt(item.error.httpCode) || 500;

  // Try parsing from error.message (most common shape)
  const parsed = extractPhpBody(item.error.message);

  if (parsed) {
    response = parsed;
  } else if (item.error.context?.data) {
    try {
      response = JSON.parse(item.error.context.data);
    } catch (e) {
      response = { status: 'error', error_detail: item.error.message };
    }
  } else {
    response = { status: 'error', error_detail: item.error.message || 'Unknown error' };
  }
} else {
  response = item;
  isError = response.status === 'error' || !!response.error_detail;
}

if (isError) {
  const detail = response.error_detail || response.message || 'The payment could not be processed at this time.';

  let parentMessage;
  if (detail.includes('already been registered on this date')) {
    parentMessage = "A payment for this student has already been registered today. Please contact the Bursar on 09162583300 if this is a separate payment.";
  } else if (detail.includes('exceeds unreconciled amount')) {
    parentMessage = "The payment amount is more than what is available on this teller. Please check the receipt and try again.";
  } else if (httpCode === 404) {
    parentMessage = "We could not match this payment in our records. Please contact the Bursar on 09162583300.";
  } else {
    parentMessage = "Your payment could not be processed at this time. Please contact the Bursar on 09162583300.";
  }

  return {
    json: {
      ...response,
      process_success: false,
      http_code: httpCode,
      error_display_message: parentMessage,
      raw_error_detail: detail
    }
  };
}

// 2. Success path
const base64String = response.data?.receipt_image || response.receipt_image;

if (!base64String) {
  return {
    json: {
      ...response,
      process_success: false,
      error_display_message: "Payment was recorded, but the receipt image could not be generated. Please contact the Bursar on 09162583300 for a copy."
    }
  };
}

const binaryData = Buffer.from(base64String, 'base64');

return {
  binary: {
    data: {
      data: binaryData.toString('base64'),
      fileName: 'partial_receipt.png',
      fileExtension: 'png',
      mimeType: 'image/png'
    }
  },
  json: {
    ...response,
    process_success: true
  }
};

// 1. Correctly navigate the WhatsApp JSON structure
// We look for the body inside the first message of the array
const rawInput = $('Message Type').first().json.messages[0].text?.body || "";

let input = rawInput
  .replace(/[\u200B-\u200D\uFEFF]/g, "") // Removes Zero-Width spaces
  .trim();

// 2. Identify Intent
const intentRegex = /^(BALANCE|BILL|STATUS|RECEIPT|OPTOUT):\s*/i;
const intentMatch = input.match(intentRegex);

if (!intentMatch) { 
  return { 
    template_matched: false, 
    reason: "No keyword found", 
    observed_input: input // This will now show the actual text
  };
}

const rawIntent = intentMatch[1].toUpperCase();
const intentMap = { 
  'BALANCE': 'balance', 
  'BILL': 'invoice', 
  'STATUS': 'status', 
  'RECEIPT': 'receipt',
  'OPTOUT': 'optout' 
};

// 3. Strict Level Map
const levelMap = {
  'junior secondary 1': ['js1', 'jss1', 'basic7', 'js 1', 'jss 1', 'basic 7'],
  'junior secondary 2': ['js2', 'jss2', 'basic8', 'js 2', 'jss 2', 'basic 8'],
  'junior secondary 3': ['js3', 'jss3', 'basic9', 'js 3', 'jss 3', 'basic 9'],
  'senior secondary 1': ['ss1', 'sss1', 'ss 1', 'sss 1'],
  'senior secondary 2': ['ss2', 'sss2', 'ss 2', 'sss 2'],
  'senior secondary 3': ['ss3', 'sss3', 'ss 3', 'sss 3']
};

// 4. Extract body and split
const body = input.replace(intentRegex, "");
const parts = body.split(',').map(p => p.trim()).filter(p => p.length > 0);
const now = new Date();

let student_name = "";
let normalized_level = "";
//let academic_session = "2024"; 
let academic_session = $input.first().json.academic_session;
let term = $input.first().json.term_of_session;

parts.forEach(part => {
    const lowerPart = part.toLowerCase();

    // Check for Academic Year (e.g. 2024 or 2024/25)
    if (/\b20\d{2}/.test(part)) {
        academic_session = part.split('/')[0].trim();
    } 
    // Check for Term
    else if (/^[1-3]$/.test(part)) {
        term = part;
    }
    // Check against Level Map
    else {
        let matchedAClass = false;
        for (const [formalName, variations] of Object.entries(levelMap)) {
            if (variations.includes(lowerPart)) {
                normalized_level = formalName;
                matchedAClass = true;
                break;
            }
        }
        // Capture Name if it's not a class
        if (!matchedAClass && /[a-zA-Z]/.test(part)) {
            student_name = part.replace(/\b\w/g, l => l.toUpperCase());
        }
    }
});

return {
  template_matched: true,
  intent: intentMap[rawIntent],
  student_name,
  normalized_level,
  academic_session,
  term,
  is_retry: false,
  wa_id:  $('Message Type').first().json.contacts?.[0]?.wa_id || "" // Keeping the ID for the reply
};

