// 1. Get the string from the AI
const rawOutput = items[0].json.output;

// 2. Remove the Markdown backticks using Regex
const cleanJsonString = rawOutput.replace(/```json|```/g, "").trim();

// 3. Parse the string into an actual JSON object
const parsedData = JSON.parse(cleanJsonString);

return [{
  json: parsedData
}];

// 1. Gather context from AI CleanUP
const cleanUp = $('AI CleanUP').first().json;
const parentInputName = cleanUp.student_name.toLowerCase().trim();
const intent = cleanUp.intent;
const parentTokens = parentInputName.split(/\s+/).filter(t => t.length > 2);

const baseResponse = {
  intent,
  original_query: parentInputName,
  is_retry: true,
  term: cleanUp.term,
  academic_session: cleanUp.academic_session
};

// 2. Determine which upstream node provided the student list.
//    Try the level-filtered node first; fall back to the name-filtered node.
let studentsFromDb = [];
let dataSource = '';

try {
  const levelResults = $('AI Fetch Class Students').all();
  if (levelResults && levelResults.length > 0) {
    studentsFromDb = levelResults;
    dataSource = 'level';
  }
} catch (e) {}

if (studentsFromDb.length === 0) {
  try {
    const nameResults = $('AI Check All Students').all();
    if (nameResults && nameResults.length > 0) {
      studentsFromDb = nameResults;
      dataSource = 'name_search';
    }
  } catch (e) {}
}

if (studentsFromDb.length === 0) {
  return {
    ...baseResponse,
    match_found: false,
    is_ambiguous: false,
    data_source: dataSource || 'none',
    message: 'No student records were available to search.'
  };
}

// 3. Levenshtein distance
function getLevenshteinDistance(a, b) {
  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

// 4. Score every candidate
const results = studentsFromDb.map(item => {
  const dbFullName = (item.json.full_name || '').toLowerCase().trim();
  const dbTokens = dbFullName.split(/\s+/);

  // Token match
  let matchedTokens = 0;
  parentTokens.forEach(pToken => {
    if (dbTokens.some(dbToken => dbToken.includes(pToken) || pToken.includes(dbToken))) {
      matchedTokens++;
    }
  });
  const tokenScore = parentTokens.length > 0 ? (matchedTokens / parentTokens.length) : 0;

  // Fuzzy score
  const distance = getLevenshteinDistance(parentInputName, dbFullName);
  const maxLength = Math.max(parentInputName.length, dbFullName.length);
  const fuzzyConfidence = maxLength === 0 ? 0 : 1 - (distance / maxLength);

  let finalScore = fuzzyConfidence;
  if (tokenScore === 1) {
    finalScore = Math.max(finalScore, 0.95);
  } else if (tokenScore >= 0.5) {
    finalScore = Math.max(finalScore, 0.85);
  }

  // When coming from name_search, the SQL has already matched on first+last tokens.
  // Give a small floor boost so valid results clear the 0.8 threshold even with
  // middle-name padding in the DB full_name that inflates Levenshtein distance.
  if (dataSource === 'name_search' && tokenScore >= 0.5) {
    finalScore = Math.max(finalScore, 0.82);
  }

  return { ...item.json, match_confidence: finalScore };
});

// 5. Filter and sort
const likelyMatches = results
  .filter(r => r.match_confidence >= 0.8)
  .sort((a, b) => b.match_confidence - a.match_confidence);

// 6. Ambiguity check
if (likelyMatches.length > 1) {
  const scoreDiff = likelyMatches[0].match_confidence - likelyMatches[1].match_confidence;
  if (scoreDiff < 0.05) {
    return {
      ...baseResponse,
      match_found: false,
      is_ambiguous: true,
      data_source: dataSource,
      potential_matches: likelyMatches.map(m => m.full_name),
      message: 'Multiple students found with similar names.'
    };
  }
}

// 7. Success
if (likelyMatches.length > 0) {
  return {
    ...baseResponse,
    match_found: true,
    is_ambiguous: false,
    data_source: dataSource,
    student_id: likelyMatches[0].student_id,
    full_name: likelyMatches[0].full_name,
    level_name: likelyMatches[0].level_name,
    confidence: Math.round(likelyMatches[0].match_confidence * 100) + '%'
  };
}

// 8. No match
return {
  ...baseResponse,
  match_found: false,
  is_ambiguous: false,
  data_source: dataSource,
  message: 'No student found matching the provided name.'
};

// -----------------------------
// RESILIENT RECEIPT MATCHER v5
// -----------------------------

// 1) Gather incoming items
const incoming = $input.all();

// ---------- Utilities ----------
const safeString = (v) => (v === null || v === undefined) ? "" : String(v);

const getTokens = (str) => {
  return safeString(str).toLowerCase()
    .replace(/[^a-z0-9 ]/g, " ")
    .split(/\s+/)
    .filter(w => w && w.length > 2);
};

function normalizeAmount(val) {
  if (val === null || val === undefined) return null;
  const s = safeString(val).replace(/,/g, "").trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function normalizeDate(val) {
  if (!val) return null;
  const s = safeString(val).trim();
  const iso = s.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  return null;
}

function extractReceiptDateAndAmount(receiptObj) {
  const receiptAmount = normalizeAmount(receiptObj.amount ?? receiptObj.total ?? null);
  const receiptDate = normalizeDate(receiptObj.date ?? receiptObj.payment_date ?? null);
  return { receiptAmount, receiptDate };
}

function safeGetNodeItems(nodeName) {
  try { return $items(nodeName) || []; } catch (e) { return []; }
}

// 2) Identify bank statement rows from incoming
const bankItems = incoming.filter(it => it.json.bank_statement_id !== undefined || it.json.total_bank_amount !== undefined);

// 3) Receipt source: ONLY from "Code in JavaScript"
const receiptItems = safeGetNodeItems("Code in JavaScript");
const receipt = receiptItems.length ? receiptItems[0].json : {};

// Build receiptText for scoring
const receiptText = (
  safeString(receipt.full_text) || 
  safeString(receipt.narration) || 
  JSON.stringify(receipt)
).toLowerCase();

// 4) Score by narration token overlap
const scored = bankItems.map(item => {
  const bankDesc = item.json.description || "";
  const bankTokens = getTokens(bankDesc);
  let matchCount = 0;
  for (const token of bankTokens) {
    if (receiptText.includes(token)) matchCount++;
  }
  const matchRatio = bankTokens.length ? (matchCount / bankTokens.length) : 0;

  item.json.match_confidence = Math.round(matchRatio * 100);
  item.json.matched = false;
  return item;
});

// 5) Unique amount + date forced match logic
const THRESHOLD = 40;
const { receiptAmount, receiptDate } = extractReceiptDateAndAmount(receipt);
let finalResults = [];

if (receiptAmount !== null && receiptDate) {
  const candidates = scored.filter(item => {
    const bankAmt = normalizeAmount(item.json.total_bank_amount);
    const bankDate = normalizeDate(item.json.payment_date);
    return bankAmt === receiptAmount && bankDate === receiptDate;
  });

  if (candidates.length === 1) {
    const forced = candidates[0];
    forced.json.match_confidence = 95;
    forced.json.matched = true;
    forced.json.match_reason = "forced_match_unique_amount_and_date";
    finalResults = [forced];
  }
}

// 6) Proceed with threshold if no forced match
if (finalResults.length === 0) {
  let matches = scored.filter(item => (item.json.match_confidence || 0) >= THRESHOLD);
  if (matches.length > 0) {
    matches.sort((a, b) => b.json.match_confidence - a.json.match_confidence);
    matches.forEach(m => { m.json.matched = true; m.json.match_reason = "above_threshold"; });
    finalResults = matches;
  }
}

// 7) THE CRITICAL FALLBACK: If still no results, return a SAFE dummy object
if (finalResults.length === 0) {
  return [{
    json: {
      teller_no: "N/A",
      unreconciled_amount: 0,
      payment_date: "1970-01-01",
      match_confidence: 0,
      matched: false,
      match_reason: "no_unreconciled_payment_found"
    }
  }];
}

// 8) Ensure n8n data format
return finalResults.map(item => item.json ? item : { json: item });

// 1. Get the caption from the image or document
const msg = $input.first().json.messages[0];
const rawCaption = (msg.image?.caption || msg.document?.caption || "").toLowerCase();

// 2. REGEX for Level (Captures JS, JSS, SS, SSS + 1, 2, or 3)
const levelRegex = /(jss|js|sss|ss)\s*([1-3])/i;
const levelMatch = rawCaption.match(levelRegex);

let normalizedLevel = "unknown";
if (levelMatch) {
    const type = levelMatch[1].toLowerCase();
    const num = levelMatch[2];

    // Map abbreviations to the exact strings in your tb_academic_levels table
    if (type.includes('j')) {
        normalizedLevel = `junior secondary ${num}`;
    } else if (type.includes('s')) {
        normalizedLevel = `senior secondary ${num}`;
    }
}

// 3. Extract and Clean Student Name
// Removes the level abbreviation and common "noise" words
let cleanedName = rawCaption
    .replace(levelRegex, "") 
    .replace(/(payment|attached|receipt|of|fees|school|student|name|is|at|the|dear|bursar)/gi, "")
    .replace(/[^\w\s]/g, "") // Remove punctuation
    .trim();

// 4. Split name into individual words for the SQL query
// We filter out any remaining short words (less than 2 chars)
const nameParts = cleanedName.split(/\s+/).filter(part => part.length > 2);

// We ensure at least two parts are sent to SQL. 
// If the parent only wrote one name, part 2 will repeat part 1 to avoid a query error.
const part1 = nameParts[0] || "unknown";
const part2 = nameParts[1] || part1;

return {
    student_name_raw: cleanedName,
    name_part_1: part1,
    name_part_2: part2,
    level: normalizedLevel,
    raw_caption: rawCaption
